# R reference values for gaply_core::stats_dist's chi-square upper tail beyond
# 2,401 degrees of freedom (Research OS, Phase 9B-1, decision 699): Bartlett's
# test of sphericity over p items has p (p - 1) / 2 degrees of freedom, 1,225 at
# 50 items and 8,128 at 128.
#
# Run by its full path, from anywhere:
#
#   /usr/local/bin/Rscript make_factor_dist_fixtures.R
#
# R is the reference, run outside Gaply (ADR-008): nothing of R is copied into
# Gaply. Base R only (stats). The five earlier scripts (make_dist_fixtures.R,
# make_xtab_dist_fixtures.R, make_ranks_dist_fixtures.R,
# make_signed_rank_dist_fixtures.R, make_linreg_dist_fixtures.R) are separate and
# not run by this one, so their files stay byte for byte. Writes, next to this
# script, chi_p_factor.tsv: a '#' header naming this script, R's version and the
# call, then a tab-separated body with every number as %.17g:
#
#   x  df  tail  p      p = pchisq(x, df, lower.tail = FALSE)
#
# Each x is qchisq(tail, df, lower.tail = FALSE) at an upper tail of 0.9, 0.5,
# 0.1, 0.05, 0.01, 1e-4, 1e-8, 1e-12, 1e-30, 1e-100 or 1e-300, and the row holds
# R's p of that exact double, not the tail. A quantile that is not finite is
# skipped and counted on the header's last line.
#
# Synthetic grids only. No manuscript or data of anyone's is read.

args <- commandArgs(trailingOnly = FALSE)
script <- sub("^--file=", "", args[grep("^--file=", args)])
here <- dirname(normalizePath(script))

f17 <- function(x) sprintf("%.17g", as.numeric(x))

dfs <- c(1225, 2346, 2415, 3000, 4000, 6000, 8000, 8128)
tails <- c(0.9, 0.5, 0.1, 0.05, 0.01, 1e-4, 1e-8, 1e-12, 1e-30, 1e-100, 1e-300)
rows <- character(0)
skipped <- 0L
for (df in dfs) {
  for (tail in tails) {
    x <- qchisq(tail, df, lower.tail = FALSE)
    if (!is.finite(x)) {
      skipped <- skipped + 1L
      next
    }
    rows <- c(rows, paste(f17(x), f17(df), f17(tail), f17(pchisq(x, df, lower.tail = FALSE)), sep = "\t"))
  }
}
path <- file.path(here, "chi_p_factor.tsv")
writeLines(c(
  "# R's upper tail of the chi-square beyond df 2,401, for gaply_core::stats_dist (Research OS, Phase 9B-1).",
  "# Generated by /usr/local/bin/Rscript make_factor_dist_fixtures.R (do not edit by hand).",
  sprintf("# %s, %s; pchisq(x, df, lower.tail = FALSE), x = qchisq(tail, df, lower.tail = FALSE).", R.version.string, R.version$arch),
  sprintf("# %d rows; %d non-finite quantiles skipped.", length(rows), skipped),
  "x\tdf\ttail\tp",
  rows), path)
cat(sprintf("chi_p_factor.tsv: %d rows, %d skipped\n", length(rows), skipped))
